begin;

-- System V3 / Integrity reporting reliability (#994).
--
-- Protected reports use the canonical actor-bound S2 operation receipt. Fully
-- anonymous reports cannot safely use that actor-bound ledger, so they receive
-- a separate private replay envelope which stores only hashes plus a minimal
-- response snapshot. The anonymous recovery capability is generated by the
-- client and only its SHA-256 hash is persisted, allowing a committed/lost
-- response to be recovered without storing the plaintext recovery secret.
select public.v3_register_migration_contract(
  '20261019210500_v3_integrity_create_idempotency',
  1,
  'forward_fix_only',
  false,
  null,
  'Canonical retry-safe Integrity case creation; protected reports use S2 receipts and anonymous reports use a private hash-only replay envelope'
);

create table if not exists private.v3_anonymous_integrity_create_operations (
  operation_id uuid primary key,
  idempotency_hash text not null unique,
  request_fingerprint text not null,
  recovery_secret_hash text not null,
  case_id uuid not null unique references public.integrity_cases(id) on delete cascade,
  response_snapshot jsonb not null,
  created_at timestamptz not null default now(),
  constraint v3_anonymous_integrity_idempotency_hash_check
    check (idempotency_hash ~ '^[0-9a-f]{64}$'),
  constraint v3_anonymous_integrity_request_fingerprint_check
    check (request_fingerprint ~ '^[0-9a-f]{64}$'),
  constraint v3_anonymous_integrity_recovery_hash_check
    check (recovery_secret_hash ~ '^[0-9a-f]{64}$'),
  constraint v3_anonymous_integrity_response_snapshot_check
    check (
      jsonb_typeof(response_snapshot) = 'object'
      and pg_column_size(response_snapshot) <= 4096
    )
);

create index if not exists v3_anonymous_integrity_create_operations_created_idx
  on private.v3_anonymous_integrity_create_operations (created_at desc);

revoke all on table private.v3_anonymous_integrity_create_operations
  from public, anon, authenticated;
grant select on table private.v3_anonymous_integrity_create_operations
  to service_role;

-- One canonical physical writer for both V3 and compatibility creation paths.
-- Browser roles never execute this helper directly.
create or replace function private.v3_insert_integrity_case(
  p_identity_mode text,
  p_reporter_user_id uuid,
  p_case_kind text,
  p_category text,
  p_summary text,
  p_details text,
  p_observed_facts text,
  p_uncertainties text,
  p_related_countries text[],
  p_edition_reference text,
  p_recovery_secret_hash text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, private, extensions
as $insert_case$
declare
  v_identity_mode text := lower(btrim(coalesce(p_identity_mode, '')));
  v_case_kind text := lower(btrim(coalesce(p_case_kind, 'report')));
  v_category text := lower(btrim(coalesce(p_category, '')));
  v_summary text := btrim(coalesce(p_summary, ''));
  v_details text := btrim(coalesce(p_details, ''));
  v_observed_facts text := nullif(btrim(coalesce(p_observed_facts, '')), '');
  v_uncertainties text := nullif(btrim(coalesce(p_uncertainties, '')), '');
  v_related_countries text[] := coalesce(p_related_countries, '{}'::text[]);
  v_edition_reference text := nullif(btrim(coalesce(p_edition_reference, '')), '');
  v_priority text := 'standard';
  v_case_id uuid;
  v_code text;
  v_created_at timestamptz;
  v_attempt integer := 0;
begin
  if v_identity_mode not in ('anonymous', 'sealed', 'confidential') then
    raise exception using errcode = '22023', message = 'VALIDATION';
  end if;
  if (v_identity_mode = 'anonymous' and p_reporter_user_id is not null)
     or (v_identity_mode <> 'anonymous' and p_reporter_user_id is null) then
    raise exception using errcode = '22023', message = 'VALIDATION';
  end if;
  if v_identity_mode = 'anonymous' then
    if p_recovery_secret_hash is null
       or p_recovery_secret_hash !~ '^[0-9a-f]{64}$' then
      raise exception using errcode = '22023', message = 'VALIDATION';
    end if;
  elsif p_recovery_secret_hash is not null then
    raise exception using errcode = '22023', message = 'VALIDATION';
  end if;
  if v_case_kind not in ('report', 'self_report', 'rule_question', 'vulnerability', 'safety') then
    raise exception using errcode = '22023', message = 'VALIDATION';
  end if;
  if v_category not in (
    'voting_integrity', 'vote_coordination', 'entry_eligibility', 'account_abuse',
    'conduct', 'safety', 'privacy', 'technical_exploit', 'tsbc_conduct', 'other'
  ) then
    raise exception using errcode = '22023', message = 'VALIDATION';
  end if;
  if char_length(v_summary) < 5 or char_length(v_summary) > 180 then
    raise exception using errcode = '22023', message = 'VALIDATION';
  end if;
  if char_length(v_details) < 20 or char_length(v_details) > 12000 then
    raise exception using errcode = '22023', message = 'VALIDATION';
  end if;
  if coalesce(array_length(v_related_countries, 1), 0) > 12 then
    raise exception using errcode = '22023', message = 'VALIDATION';
  end if;

  if v_category = 'safety' or v_case_kind = 'safety' then
    v_priority := 'urgent';
  elsif v_category in ('voting_integrity', 'vote_coordination', 'technical_exploit', 'privacy') then
    v_priority := 'high';
  elsif v_case_kind = 'rule_question' then
    v_priority := 'information';
  end if;

  loop
    v_attempt := v_attempt + 1;
    v_code := case v_identity_mode
      when 'anonymous' then 'AR-'
      when 'sealed' then 'SR-'
      else 'CR-'
    end || upper(encode(extensions.gen_random_bytes(5), 'hex'));

    exit when not exists (
      select 1
      from public.integrity_cases existing_case
      where existing_case.public_code = v_code
    );

    if v_attempt > 8 then
      raise exception using errcode = 'P0001', message = 'DATABASE';
    end if;
  end loop;

  insert into public.integrity_cases (
    public_code,
    case_kind,
    category,
    identity_mode,
    reporter_user_id,
    summary,
    details,
    observed_facts,
    uncertainties,
    related_countries,
    edition_reference,
    status,
    priority
  )
  values (
    v_code,
    v_case_kind,
    v_category,
    v_identity_mode,
    p_reporter_user_id,
    v_summary,
    v_details,
    v_observed_facts,
    v_uncertainties,
    v_related_countries,
    v_edition_reference,
    'received',
    v_priority
  )
  returning id, created_at into v_case_id, v_created_at;

  if v_identity_mode = 'anonymous' then
    insert into public.integrity_case_access (case_id, recovery_secret_hash)
    values (v_case_id, p_recovery_secret_hash);
  end if;

  insert into public.integrity_case_messages (
    case_id,
    author_role,
    body,
    created_by
  )
  values (
    v_case_id,
    'reporter',
    v_details,
    p_reporter_user_id
  );

  insert into public.integrity_case_events (
    case_id,
    event_type,
    detail,
    actor_user_id
  )
  values (
    v_case_id,
    'case.created',
    case v_identity_mode
      when 'anonymous' then 'Anonymous case received'
      when 'sealed' then 'Sealed-identity case received'
      else 'Confidential case received'
    end,
    p_reporter_user_id
  );

  return jsonb_build_object(
    'caseId', v_case_id,
    'caseCode', v_code,
    'status', 'received',
    'priority', v_priority,
    'createdAt', v_created_at
  );
end
$insert_case$;

revoke all on function private.v3_insert_integrity_case(
  text, uuid, text, text, text, text, text, text, text[], text, text
) from public, anon, authenticated;

create or replace function public.v3_create_anonymous_integrity_case(
  p_operation_id uuid,
  p_idempotency_key text,
  p_recovery_key text,
  p_category text,
  p_summary text,
  p_details text,
  p_observed_facts text default null,
  p_uncertainties text default null,
  p_related_countries text[] default '{}'::text[],
  p_edition_reference text default null,
  p_case_kind text default 'report'
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, private, extensions
as $create_anonymous$
declare
  v_key text := btrim(coalesce(p_idempotency_key, ''));
  v_recovery_raw text := public.integrity_normalize_secret(p_recovery_key);
  v_recovery_pretty text;
  v_recovery_hash text;
  v_idempotency_hash text;
  v_category text := lower(btrim(coalesce(p_category, '')));
  v_case_kind text := lower(btrim(coalesce(p_case_kind, 'report')));
  v_summary text := btrim(coalesce(p_summary, ''));
  v_details text := btrim(coalesce(p_details, ''));
  v_observed_facts text := nullif(btrim(coalesce(p_observed_facts, '')), '');
  v_uncertainties text := nullif(btrim(coalesce(p_uncertainties, '')), '');
  v_related_countries text[] := coalesce(p_related_countries, '{}'::text[]);
  v_edition_reference text := nullif(btrim(coalesce(p_edition_reference, '')), '');
  v_fingerprint text;
  v_existing private.v3_anonymous_integrity_create_operations;
  v_created jsonb;
  v_snapshot jsonb;
begin
  if p_operation_id is null
     or char_length(v_key) < 32
     or char_length(v_key) > 256 then
    raise exception using errcode = '22023', message = 'VALIDATION';
  end if;
  if v_recovery_raw !~ '^[A-F0-9]{24}$' then
    raise exception using
      errcode = '22023',
      message = 'VALIDATION',
      hint = 'Anonymous recovery keys must contain exactly 24 hexadecimal characters.';
  end if;

  v_recovery_pretty := regexp_replace(v_recovery_raw, '(.{4})(?=.)', '\1-', 'g');
  v_recovery_hash := encode(
    extensions.digest(convert_to(v_recovery_raw, 'UTF8'), 'sha256'),
    'hex'
  );
  v_idempotency_hash := encode(
    extensions.digest(
      convert_to(p_operation_id::text || ':' || v_key, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  v_fingerprint := private.studio2_request_fingerprint(
    'integrity.case.create',
    'R1',
    jsonb_build_object('identityMode', 'anonymous'),
    jsonb_build_object(
      'identityMode', 'anonymous',
      'caseKind', v_case_kind,
      'category', v_category,
      'summary', v_summary,
      'details', v_details,
      'observedFacts', v_observed_facts,
      'uncertainties', v_uncertainties,
      'relatedCountries', to_jsonb(v_related_countries),
      'editionReference', v_edition_reference,
      'recoverySecretHash', v_recovery_hash
    )
  );

  -- Serialize both operation-id and idempotency-key races. A second request may
  -- use a different operation UUID with the same stable idempotency key, just as
  -- the authenticated S2 claim helper can reconcile to the canonical receipt.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('v3-integrity-anon-op:' || p_operation_id::text, 0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('v3-integrity-anon-key:' || v_idempotency_hash, 0)
  );

  select operation_row.*
  into v_existing
  from private.v3_anonymous_integrity_create_operations operation_row
  where operation_row.operation_id = p_operation_id
     or operation_row.idempotency_hash = v_idempotency_hash
  order by case when operation_row.operation_id = p_operation_id then 0 else 1 end
  limit 1
  for update;

  if v_existing.operation_id is not null then
    if v_existing.idempotency_hash is distinct from v_idempotency_hash
       or v_existing.request_fingerprint is distinct from v_fingerprint
       or v_existing.recovery_secret_hash is distinct from v_recovery_hash then
      raise exception using
        errcode = 'P0001',
        message = 'IDEMPOTENCY_CONFLICT',
        hint = 'Use the original anonymous submission payload and recovery capability, or create a new operation.';
    end if;

    return v_existing.response_snapshot
      || jsonb_build_object(
        'recovery_key', v_recovery_pretty,
        'operationId', v_existing.operation_id,
        'replayed', true
      );
  end if;

  -- Recovery of a previously committed operation happens above this gate. Only
  -- genuinely new reports are suppressed by Read-only/Maintenance.
  if not coalesce(private.studio2_platform_mutation_allowed('integrity.case.create'), false) then
    raise exception using errcode = '25006', message = 'STATE_CHANGED';
  end if;

  v_created := private.v3_insert_integrity_case(
    'anonymous',
    null,
    v_case_kind,
    v_category,
    v_summary,
    v_details,
    v_observed_facts,
    v_uncertainties,
    v_related_countries,
    v_edition_reference,
    v_recovery_hash
  );

  v_snapshot := jsonb_build_object(
    'ok', true,
    'case_code', v_created ->> 'caseCode',
    'status', v_created ->> 'status',
    'priority', v_created ->> 'priority',
    'created_at', v_created ->> 'createdAt'
  );

  insert into private.v3_anonymous_integrity_create_operations (
    operation_id,
    idempotency_hash,
    request_fingerprint,
    recovery_secret_hash,
    case_id,
    response_snapshot
  )
  values (
    p_operation_id,
    v_idempotency_hash,
    v_fingerprint,
    v_recovery_hash,
    (v_created ->> 'caseId')::uuid,
    v_snapshot
  );

  return v_snapshot
    || jsonb_build_object(
      'recovery_key', v_recovery_pretty,
      'operationId', p_operation_id,
      'replayed', false
    );
end
$create_anonymous$;

revoke all on function public.v3_create_anonymous_integrity_case(
  uuid, text, text, text, text, text, text, text, text[], text, text
) from public;
grant execute on function public.v3_create_anonymous_integrity_case(
  uuid, text, text, text, text, text, text, text, text[], text, text
) to anon, authenticated;

comment on function public.v3_create_anonymous_integrity_case(
  uuid, text, text, text, text, text, text, text, text[], text, text
) is
  'Retry-safe fully anonymous Integrity case creation. Plaintext idempotency and recovery secrets are never persisted.';

create or replace function public.v3_reconcile_anonymous_integrity_case(
  p_operation_id uuid,
  p_idempotency_key text,
  p_recovery_key text
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, private, extensions
as $reconcile_anonymous$
declare
  v_key text := btrim(coalesce(p_idempotency_key, ''));
  v_recovery_raw text := public.integrity_normalize_secret(p_recovery_key);
  v_recovery_pretty text;
  v_recovery_hash text;
  v_idempotency_hash text;
  v_operation private.v3_anonymous_integrity_create_operations;
begin
  if p_operation_id is null
     or char_length(v_key) < 32
     or char_length(v_key) > 256
     or v_recovery_raw !~ '^[A-F0-9]{24}$' then
    raise exception using errcode = '22023', message = 'VALIDATION';
  end if;

  v_recovery_pretty := regexp_replace(v_recovery_raw, '(.{4})(?=.)', '\1-', 'g');
  v_recovery_hash := encode(
    extensions.digest(convert_to(v_recovery_raw, 'UTF8'), 'sha256'),
    'hex'
  );
  v_idempotency_hash := encode(
    extensions.digest(
      convert_to(p_operation_id::text || ':' || v_key, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  select operation_row.*
  into v_operation
  from private.v3_anonymous_integrity_create_operations operation_row
  where operation_row.operation_id = p_operation_id
    and operation_row.idempotency_hash = v_idempotency_hash
    and operation_row.recovery_secret_hash = v_recovery_hash
  limit 1;

  if v_operation.operation_id is null then
    -- Deliberately identical for unknown operation, wrong idempotency key and
    -- wrong recovery capability: this endpoint must not become a case probe.
    raise exception using errcode = 'P0002', message = 'UNKNOWN';
  end if;

  return v_operation.response_snapshot
    || jsonb_build_object(
      'recovery_key', v_recovery_pretty,
      'operationId', v_operation.operation_id,
      'replayed', true
    );
end
$reconcile_anonymous$;

revoke all on function public.v3_reconcile_anonymous_integrity_case(uuid, text, text)
  from public;
grant execute on function public.v3_reconcile_anonymous_integrity_case(uuid, text, text)
  to anon, authenticated;

comment on function public.v3_reconcile_anonymous_integrity_case(uuid, text, text) is
  'Lost-response recovery for anonymous Integrity creation. Requires all three high-entropy capabilities and returns no case for a mismatch.';

create or replace function public.v3_create_protected_integrity_case(
  p_operation_id uuid,
  p_idempotency_key text,
  p_identity_mode text,
  p_case_kind text,
  p_category text,
  p_summary text,
  p_details text,
  p_observed_facts text default null,
  p_uncertainties text default null,
  p_related_countries text[] default '{}'::text[],
  p_edition_reference text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, private, extensions
as $create_protected$
declare
  v_actor uuid := auth.uid();
  v_identity_mode text := lower(btrim(coalesce(p_identity_mode, '')));
  v_case_kind text := lower(btrim(coalesce(p_case_kind, 'report')));
  v_category text := lower(btrim(coalesce(p_category, 'other')));
  v_summary text := btrim(coalesce(p_summary, ''));
  v_details text := btrim(coalesce(p_details, ''));
  v_observed_facts text := nullif(btrim(coalesce(p_observed_facts, '')), '');
  v_uncertainties text := nullif(btrim(coalesce(p_uncertainties, '')), '');
  v_related_countries text[] := coalesce(p_related_countries, '{}'::text[]);
  v_edition_reference text := nullif(btrim(coalesce(p_edition_reference, '')), '');
  v_claim jsonb;
  v_canonical_operation_id uuid;
  v_created jsonb;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'AUTHENTICATION';
  end if;
  if v_identity_mode not in ('sealed', 'confidential') then
    raise exception using errcode = '22023', message = 'VALIDATION';
  end if;

  v_claim := private.studio2_claim_operation(
    p_operation_id,
    p_idempotency_key,
    p_operation_id,
    'integrity.case.create',
    'R1',
    jsonb_build_object('identityMode', v_identity_mode),
    jsonb_build_object(
      'identityMode', v_identity_mode,
      'caseKind', v_case_kind,
      'category', v_category,
      'summary', v_summary,
      'details', v_details,
      'observedFacts', v_observed_facts,
      'uncertainties', v_uncertainties,
      'relatedCountries', to_jsonb(v_related_countries),
      'editionReference', v_edition_reference
    )
  );

  v_canonical_operation_id := (v_claim ->> 'operationId')::uuid;

  if coalesce((v_claim ->> 'replayed')::boolean, false) then
    if v_claim ->> 'status' = 'succeeded' then
      return coalesce(v_claim -> 'result', '{}'::jsonb)
        || jsonb_build_object('replayed', true);
    end if;

    return jsonb_build_object(
      'ok', false,
      'operationId', v_canonical_operation_id,
      'replayed', true,
      'status', v_claim ->> 'status',
      'error', v_claim -> 'error'
    );
  end if;

  v_created := private.v3_insert_integrity_case(
    v_identity_mode,
    v_actor,
    v_case_kind,
    v_category,
    v_summary,
    v_details,
    v_observed_facts,
    v_uncertainties,
    v_related_countries,
    v_edition_reference,
    null
  );

  v_result := jsonb_build_object(
    'ok', true,
    'case_id', v_created ->> 'caseId',
    'case_code', v_created ->> 'caseCode',
    'status', v_created ->> 'status',
    'priority', v_created ->> 'priority',
    'created_at', v_created ->> 'createdAt',
    'operationId', v_canonical_operation_id,
    'receiptId', v_canonical_operation_id
  );

  perform private.studio2_complete_operation(v_canonical_operation_id, v_result);

  return v_result || jsonb_build_object('replayed', false);
end
$create_protected$;

revoke all on function public.v3_create_protected_integrity_case(
  uuid, text, text, text, text, text, text, text, text, text[], text
) from public, anon;
grant execute on function public.v3_create_protected_integrity_case(
  uuid, text, text, text, text, text, text, text, text, text[], text
) to authenticated;

comment on function public.v3_create_protected_integrity_case(
  uuid, text, text, text, text, text, text, text, text, text[], text
) is
  'Actor-bound R1 Integrity case creation with canonical S2 semantic idempotency, receipt and lost-response reconciliation.';

-- Preserve the old browser RPC signatures during Public cutover, but make them
-- compatibility adapters rather than independent Integrity writers.
create or replace function public.public_create_anonymous_integrity_case(
  _category text,
  _summary text,
  _details text,
  _observed_facts text default null,
  _uncertainties text default null,
  _related_countries text[] default '{}'::text[],
  _edition_reference text default null,
  _case_kind text default 'report'
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, private, extensions
as $legacy_anonymous$
declare
  v_operation_id uuid := extensions.gen_random_uuid();
  v_idempotency_key text := encode(extensions.gen_random_bytes(16), 'hex');
  v_recovery_key text := upper(encode(extensions.gen_random_bytes(12), 'hex'));
  v_result jsonb;
begin
  v_result := public.v3_create_anonymous_integrity_case(
    v_operation_id,
    v_idempotency_key,
    v_recovery_key,
    _category,
    _summary,
    _details,
    _observed_facts,
    _uncertainties,
    _related_countries,
    _edition_reference,
    _case_kind
  );

  return v_result - 'operationId' - 'replayed';
end
$legacy_anonymous$;

revoke all on function public.public_create_anonymous_integrity_case(
  text, text, text, text, text, text[], text, text
) from public;
grant execute on function public.public_create_anonymous_integrity_case(
  text, text, text, text, text, text[], text, text
) to anon, authenticated;

create or replace function public.create_protected_integrity_case(
  _identity_mode text,
  _case_kind text,
  _category text,
  _summary text,
  _details text,
  _observed_facts text default null,
  _uncertainties text default null,
  _related_countries text[] default '{}'::text[],
  _edition_reference text default null
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, private, extensions
as $legacy_protected$
declare
  v_operation_id uuid := extensions.gen_random_uuid();
  v_idempotency_key text := encode(extensions.gen_random_bytes(16), 'hex');
  v_result jsonb;
begin
  v_result := public.v3_create_protected_integrity_case(
    v_operation_id,
    v_idempotency_key,
    _identity_mode,
    _case_kind,
    _category,
    _summary,
    _details,
    _observed_facts,
    _uncertainties,
    _related_countries,
    _edition_reference
  );

  return jsonb_build_object(
    'ok', coalesce((v_result ->> 'ok')::boolean, false),
    'case_id', v_result ->> 'case_id',
    'case_code', v_result ->> 'case_code'
  );
end
$legacy_protected$;

revoke all on function public.create_protected_integrity_case(
  text, text, text, text, text, text, text, text[], text
) from public;
grant execute on function public.create_protected_integrity_case(
  text, text, text, text, text, text, text, text[], text
) to authenticated;

notify pgrst, 'reload schema';

commit;
